   135	/** @internal
   136	 * @handles a data received event. It then calls the handlers for the different packet types
   137	 * or and exception handler callback.
   138	 * @param user pointer to current ssh_session
   139	 * @param data pointer to the data received
   140	 * @len length of data received. It might not be enough for a complete packet
   141	 * @returns number of bytes read and processed.
   142	 */
   143	int ssh_packet_socket_callback(const void *data, size_t receivedlen, void *user)
   144	{
   145	    ssh_session session= (ssh_session) user;
   146	    unsigned int blocksize = (session->current_crypto ?
   147	                              session->current_crypto->in_cipher->blocksize : 8);
   148	    unsigned int lenfield_blocksize = (session->current_crypto ?
   149	                                  session->current_crypto->in_cipher->lenfield_blocksize : 8);
   150	    size_t current_macsize = 0;
   151	    uint8_t *ptr = NULL;
   152	    int to_be_read;
   153	    int rc;
   154	    uint8_t *cleartext_packet = NULL;
   155	    uint8_t *packet_second_block = NULL;
   156	    uint8_t *mac = NULL;
   157	    size_t packet_remaining;
   158	    uint32_t packet_len, compsize, payloadsize;
   159	    uint8_t padding;
   160	    size_t processed = 0; /* number of byte processed from the callback */
   161	
   162	    if(session->current_crypto != NULL) {
   163	      current_macsize = hmac_digest_len(session->current_crypto->in_hmac);
   164	    }
   165	    if (lenfield_blocksize == 0) {
   166	        lenfield_blocksize = blocksize;
   167	    }
   168	    if (data == NULL) {
   169	        goto error;
   170	    }
   171	
   172	    if (session->session_state == SSH_SESSION_STATE_ERROR) {
   173	        goto error;
   174	    }
   175	#ifdef DEBUG_PACKET
   176	    SSH_LOG(SSH_LOG_PACKET,
   177	            "rcv packet cb (len=%zu, state=%s)",
   178	            receivedlen,
   179	            session->packet_state == PACKET_STATE_INIT ?
   180	                "INIT" :
   181	                session->packet_state == PACKET_STATE_SIZEREAD ?
   182	                    "SIZE_READ" :
   183	                    session->packet_state == PACKET_STATE_PROCESSING ?
   184	                    "PROCESSING" : "unknown");
   185	#endif
   186	    switch(session->packet_state) {
   187	        case PACKET_STATE_INIT:
   188	            if (receivedlen < lenfield_blocksize) {
   189	                /*
   190	                 * We didn't receive enough data to read at least one
   191	                 * block size, give up
   192	                 */
   193	#ifdef DEBUG_PACKET
   194	                SSH_LOG(SSH_LOG_PACKET,
   195	                        "Waiting for more data (%zu < %u)",
   196	                        receivedlen,
   197	                        lenfield_blocksize);
   198	#endif
   199	                return 0;
   200	            }
   201	
   202	            session->in_packet = (struct packet_struct) {
   203	                .type = 0,
   204	            };
   205	
   206	            if (session->in_buffer) {
   207	                rc = ssh_buffer_reinit(session->in_buffer);
   208	                if (rc < 0) {
   209	                    goto error;
   210	                }
   211	            } else {
   212	                session->in_buffer = ssh_buffer_new();
   213	                if (session->in_buffer == NULL) {
   214	                    goto error;
   215	                }
   216	            }
   217	
   218	            ptr = ssh_buffer_allocate(session->in_buffer, lenfield_blocksize);
   219	            if (ptr == NULL) {
   220	                goto error;
   221	            }
   222	            processed += lenfield_blocksize;
   223	            packet_len = ssh_packet_decrypt_len(session, ptr, (uint8_t *)data);
   224	
   225	            if (packet_len > MAX_PACKET_LEN) {
   226	                ssh_set_error(session,
   227	                              SSH_FATAL,
   228	                              "read_packet(): Packet len too high(%u %.4x)",
   229	                              packet_len, packet_len);
   230	                goto error;
   231	            }
   232	            to_be_read = packet_len - lenfield_blocksize + sizeof(uint32_t);
   233	            if (to_be_read < 0) {
   234	                /* remote sshd sends invalid sizes? */
