   236	                              SSH_FATAL,
   237	                              "Given numbers of bytes left to be read < 0 (%d)!",
   238	                              to_be_read);
   239	                goto error;
   240	            }
   241	
   242	            session->in_packet.len = packet_len;
   243	            session->packet_state = PACKET_STATE_SIZEREAD;
   244	            FALL_THROUGH;
   245	        case PACKET_STATE_SIZEREAD:
   246	            packet_len = session->in_packet.len;
   247	            processed = lenfield_blocksize;
   248	            to_be_read = packet_len + sizeof(uint32_t) + current_macsize;
   249	            /* if to_be_read is zero, the whole packet was blocksize bytes. */
   250	            if (to_be_read != 0) {
   251	                if (receivedlen  < (unsigned int)to_be_read) {
   252	                    /* give up, not enough data in buffer */
   253	                    SSH_LOG(SSH_LOG_PACKET,
   254	                            "packet: partial packet (read len) "
   255	                            "[len=%d, receivedlen=%d, to_be_read=%d]",
   256	                            packet_len,
   257	                            (int)receivedlen,
   258	                            to_be_read);
   259	                    return 0;
   260	                }
   261	
   262	                packet_second_block = (uint8_t*)data + lenfield_blocksize;
   263	                processed = to_be_read - current_macsize;
   264	            }
   265	
   266	            /* remaining encrypted bytes from the packet, MAC not included */
   267	            packet_remaining =
   268	                packet_len - (lenfield_blocksize - sizeof(uint32_t));
   269	            cleartext_packet = ssh_buffer_allocate(session->in_buffer,
   270	                                                   packet_remaining);
   271	            if (session->current_crypto) {
   272	                /*
   273	                 * Decrypt the rest of the packet (lenfield_blocksize bytes already
   274	                 * have been decrypted)
   275	                 */
   276	                if (packet_remaining > 0) {
   277	                    rc = ssh_packet_decrypt(session,
   278	                                            cleartext_packet,
   279	                                            (uint8_t *)data,
   280	                                            lenfield_blocksize,
   281	                                            processed - lenfield_blocksize);
   282	                    if (rc < 0) {
   283	                        ssh_set_error(session, SSH_FATAL, "Decryption error");
   284	                        goto error;
   285	                    }
   286	                }
   287	                mac = packet_second_block + packet_remaining;
   288	
   289	                rc = ssh_packet_hmac_verify(session, session->in_buffer, mac, session->current_crypto->in_hmac);
   290	                if (rc < 0) {
   291	                    ssh_set_error(session, SSH_FATAL, "HMAC error");
   292	                    goto error;
   293	                }
   294	                processed += current_macsize;
   295	            } else {
   296	                memcpy(cleartext_packet, packet_second_block, packet_remaining);
   297	            }
   298	
   299	            /* skip the size field which has been processed before */
   300	            ssh_buffer_pass_bytes(session->in_buffer, sizeof(uint32_t));
   301	
   302	            rc = ssh_buffer_get_u8(session->in_buffer, &padding);
   303	            if (rc == 0) {
   304	                ssh_set_error(session,
   305	                              SSH_FATAL,
   306	                              "Packet too short to read padding");
   307	                goto error;
   308	            }
   309	
   310	            if (padding > ssh_buffer_get_len(session->in_buffer)) {
   311	                ssh_set_error(session,
   312	                              SSH_FATAL,
   313	                              "Invalid padding: %d (%d left)",
   314	                              padding,
   315	                              ssh_buffer_get_len(session->in_buffer));
   316	                goto error;
   317	            }
   318	            ssh_buffer_pass_bytes_end(session->in_buffer, padding);
   319	            compsize = ssh_buffer_get_len(session->in_buffer);
   320	
   321	#ifdef WITH_ZLIB
   322	            if (session->current_crypto
   323	                && session->current_crypto->do_compress_in
   324	                && ssh_buffer_get_len(session->in_buffer) > 0) {
   325	                rc = decompress_buffer(session, session->in_buffer,MAX_PACKET_LEN);
   326	                if (rc < 0) {
   327	                    goto error;
   328	                }
   329	            }
   330	#endif /* WITH_ZLIB */
   331	            payloadsize = ssh_buffer_get_len(session->in_buffer);
   332	            session->recv_seq++;
   333	            if (session->raw_counter != NULL) {
   334	                session->raw_counter->in_bytes += payloadsize;
   335	                session->raw_counter->in_packets++;
   336	            }
   337	
   338	            /*
   339	             * We don't want to rewrite a new packet while still executing the
   340	             * packet callbacks
   341	             */
   342	            session->packet_state = PACKET_STATE_PROCESSING;
   343	            ssh_packet_parse_type(session);
   344	            SSH_LOG(SSH_LOG_PACKET,
   345	                    "packet: read type %hhd [len=%d,padding=%hhd,comp=%d,payload=%d]",
   346	                    session->in_packet.type, packet_len, padding, compsize, payloadsize);
